import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.Cdp8-jB6.js";const g=JSON.parse('{"title":"RFC-032 — /explore v2 context/scale-shell engine + scalable universe rendering","description":"","frontmatter":{},"headers":[],"relativePath":"rfc/RFC-032.md","filePath":"rfc/RFC-032.md"}'),n={name:"rfc/RFC-032.md"};function r(i,e,l,c,d,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="rfc-032-—-explore-v2-context-scale-shell-engine-scalable-universe-rendering" tabindex="-1">RFC-032 — /explore v2 context/scale-shell engine + scalable universe rendering <a class="header-anchor" href="#rfc-032-—-explore-v2-context-scale-shell-engine-scalable-universe-rendering" aria-label="Permalink to &quot;RFC-032 — /explore v2 context/scale-shell engine + scalable universe rendering&quot;">​</a></h1><p><em>Status: Draft (epic kickoff) · 2026-07 · Closes: PRD-030 · Tracking: #TBD · target: v2.x</em></p><blockquote><p><strong>Why this is an RFC.</strong> Extending /explore to the known universe binds architectural commitments that ripple through the core 3D route and must be right from slice 0 or every later slice forces a rewrite: (1) a <strong>nested-context / scale-shell</strong> coordinate model that survives ~20 orders of magnitude without float-precision death, (2) a <strong>scalable render vocabulary</strong> (instanced points + impostor billboards) governed by a <strong>device budget</strong>, (3) a <strong>warp transition</strong> system between contexts, (4) a <strong>lens layer</strong> extending the Science Lens, and (5) a <strong>data pipeline</strong> for real public catalogs with provenance. v1 (solar system) is context-0 and must not regress. UX/interaction is specified separately in <strong>UXS-014</strong>.</p></blockquote><h2 id="_1-·-architecture-overview" tabindex="-1">1 · Architecture overview <a class="header-anchor" href="#_1-·-architecture-overview" aria-label="Permalink to &quot;1 · Architecture overview&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/explore route</span></span>
<span class="line"><span> └─ ContextGraph — ordered stack of Contexts (SolarSystem ⊂ Neighborhood ⊂ MilkyWay ⊂ LocalGroup …)</span></span>
<span class="line"><span>     • each Context: own units + origin, own scene, own LOD/budget policy</span></span>
<span class="line"><span>     • active context renders; neighbours pre-warm on approach</span></span>
<span class="line"><span> └─ Navigator — zoom within a context; warp (1–2 s cinematic) between contexts</span></span>
<span class="line"><span> └─ Renderers (shared vocabulary):</span></span>
<span class="line"><span>     • PointField  — THREE.Points / instanced, 1 draw call, shader-colored (spectral B−V→RGB)</span></span>
<span class="line"><span>     • Impostors   — camera-facing textured quads (galaxies, nebulae, real photos)</span></span>
<span class="line"><span>     • BodyScenes  — reuse existing Keplerian orrery for exoplanet systems</span></span>
<span class="line"><span>     • LensLayer   — curvature / time / causality / property-space overlays</span></span>
<span class="line"><span> └─ Catalog — streamed, tiled real data (HYG, Exoplanet Archive, Messier/OpenNGC, …) + provenance</span></span>
<span class="line"><span> └─ Budget — detect-gpu tier → point/impostor caps (desktop ~200k, mobile ~20k)</span></span></code></pre></div><h2 id="_2-·-design-decisions-to-lock" tabindex="-1">2 · Design decisions (to lock) <a class="header-anchor" href="#_2-·-design-decisions-to-lock" aria-label="Permalink to &quot;2 · Design decisions (to lock)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>id</th><th>Decision</th><th>Rationale</th></tr></thead><tbody><tr><td><strong>C-A</strong></td><td><strong>Nested contexts, each its own coord space</strong> (not one giant world)</td><td>A single float space dies long before galaxy scale. Contexts keep every scene numerically sane; the boundary is a re-basing handoff.</td></tr><tr><td><strong>C-B</strong></td><td><strong>Zoom within, warp between</strong></td><td>Continuous zoom is the emotional reveal <em>where reachable</em> (to the Neighborhood); warp hides the unbridgeable gaps + broken precision AND teaches the distance.</td></tr><tr><td><strong>C-C</strong></td><td><strong>One render vocabulary + device budget</strong></td><td>Instanced points + impostors + a <code>detect-gpu</code> cap is the only way to scale dots on mobile+desktop and keep scaling as contexts are added.</td></tr><tr><td><strong>C-D</strong></td><td><strong>Lenses extend the Science-Lens pattern</strong></td><td>Physics (curvature/time/causality/property-space) as toggles on the same scene, not separate modes — reuse + consistency.</td></tr><tr><td><strong>C-E</strong></td><td><strong>Schematic (non-to-scale) maps past the Milky Way</strong></td><td>Galaxy distances are uncertain; a labeled schematic is honest where a fake to-scale render is not (PRD-030 principle 2).</td></tr><tr><td><strong>C-F</strong></td><td><strong>v1 untouched; v2 loads lazily at the boundary</strong></td><td>The solar-system experience + perf must not regress; universe code is a dynamic import gated on zoom-out.</td></tr><tr><td><strong>C-G</strong></td><td><strong>Real star color from B−V → blackbody → RGB</strong></td><td>Scientifically-correct color, no invented textures.</td></tr></tbody></table><h2 id="_3-·-context-model" tabindex="-1">3 · Context model <a class="header-anchor" href="#_3-·-context-model" aria-label="Permalink to &quot;3 · Context model&quot;">​</a></h2><p><code>Context</code> = <code>{ id, parent, units (m/AU/ly/pc), originTransform, enter()/leave(), renderables[], lodPolicy, budgetShare }</code>. The <code>ContextGraph</code> holds the active context + pre-warms the immediate parent/child on approach so warps are instant. Crossing a boundary re-bases the camera into the neighbour&#39;s coordinate space (the Sun→dot handoff is the SolarSystem→Neighborhood boundary). Deep-links (<code>?goto=&lt;objectId&gt;</code>) resolve an object → its context path and warp there.</p><h2 id="_4-·-render-vocabulary-the-scalable-core" tabindex="-1">4 · Render vocabulary (the scalable core) <a class="header-anchor" href="#_4-·-render-vocabulary-the-scalable-core" aria-label="Permalink to &quot;4 · Render vocabulary (the scalable core)&quot;">​</a></h2><ul><li><strong>PointField</strong> — all stars in one <code>THREE.Points</code> draw call; per-point attributes (position, magnitude, B−V); vertex/fragment shader sizes by magnitude + camera distance and colors by temperature. LOD = &quot;N brightest within radius R,&quot; N from the budget. Streamed in distance shells (tiles), not all at once.</li><li><strong>Impostors</strong> — galaxies/nebulae as camera-facing quads; for gallery objects the quad samples the <strong>real curated photo</strong>; others procedural. Cheap, scales to thousands.</li><li><strong>BodyScenes</strong> — exoplanet systems reuse the existing Keplerian engine verbatim (real period/a/e); bodies are proportional procedural spheres with honest &quot;artist&#39;s impression&quot; captions.</li><li><strong>Budget</strong> — <code>detect-gpu</code> (already in the stack) tiers the caps; the same code path renders 200k (desktop) or 20k (mobile). This is the load-bearing scalability contract from PRD-030.</li></ul><h2 id="_5-·-lenses-physics-layer" tabindex="-1">5 · Lenses (physics layer) <a class="header-anchor" href="#_5-·-lenses-physics-layer" aria-label="Permalink to &quot;5 · Lenses (physics layer)&quot;">​</a></h2><p>Each lens re-renders/overlays the active context&#39;s objects: <strong>curvature</strong> (spacetime embedding grid warped by mass, labeled analogy), <strong>time</strong> (dilation readout + light-travel-time), <strong>causality</strong> (light-cone spheres), <strong>property-space</strong> (re-project the same PointField onto physical axes — the flyable Hertzsprung-Russell diagram; exoplanet mass-vs-period). All reuse the Science-Lens toggle UX.</p><h2 id="_6-·-data-pipeline" tabindex="-1">6 · Data pipeline <a class="header-anchor" href="#_6-·-data-pipeline" aria-label="Permalink to &quot;6 · Data pipeline&quot;">​</a></h2><p>Real public catalogs → build-time normalized JSON under <code>static/data/universe/</code> (mirrors existing data pipeline), validated by schema (fail-closed), provenance-tracked, i18n-overlaid like /science. Catalogs: HYG (nearby stars), NASA Exoplanet Archive (systems), Messier + OpenNGC (deep-sky), IAU constellation lines, spiral-arm model, Local Group. Curated hero sets (exoplanets, culture doors) are hand-authored overlays on the raw catalog. Everything streamed/tiled so v1 bundle weight is untouched.</p><h2 id="_7-·-slice-contracts-what-each-slice-locks" tabindex="-1">7 · Slice contracts (what each slice locks) <a class="header-anchor" href="#_7-·-slice-contracts-what-each-slice-locks" aria-label="Permalink to &quot;7 · Slice contracts (what each slice locks)&quot;">​</a></h2><ul><li><strong>S0</strong> — <code>ContextGraph</code> + <code>Context</code> interface + <code>PointField</code> renderer + <code>Budget</code> + the SolarSystem↔Neighborhood boundary handoff. Ships: continuous zoom-out to the real HYG neighborhood, spectral colors, real starfield replaces the decorative one.</li><li><strong>S1</strong> — object selection + Panel reuse + named-star curation + constellation lines + breadcrumb + <code>?goto=</code>.</li><li><strong>S2</strong> — <code>Navigator</code> warp transition + BodyScene sub-context (exoplanet mini-orreries, real orbits).</li><li><strong>S3</strong> — /science exoplanet sections + culture-overlay pattern.</li><li><strong>S4</strong> — Impostor pipeline + deep-sky catalog + gallery↔3D bridge.</li><li><strong>S5</strong> — Milky Way context + schematic-map convention + Sag A* pin.</li><li><strong>S6</strong> — LensLayer + gravitational-lensing shader + curvature/time lenses + black-hole objects.</li><li><strong>S7</strong> — property-space projection (HR diagram) + causality lens.</li><li><strong>S8+</strong> — Local Group context + message-object trajectories + grand-tour narration.</li></ul><h2 id="_8-·-risks-open" tabindex="-1">8 · Risks / open <a class="header-anchor" href="#_8-·-risks-open" aria-label="Permalink to &quot;8 · Risks / open&quot;">​</a></h2><ul><li><strong>Precision at the boundary</strong> — validate the re-basing handoff feels seamless (S0 proves it).</li><li><strong>Mobile point budget</strong> — tune caps on real devices; graceful degradation is a first-class requirement, not an afterthought.</li><li><strong>Warp legibility</strong> — the transition must orient, not disorient (UXS-014 owns this; breadcrumb is mandatory).</li><li><strong>Data volume</strong> — tiling/streaming must keep the v1 bundle + first paint untouched (C-F).</li></ul><h2 id="_9-·-non-goals" tabindex="-1">9 · Non-goals <a class="header-anchor" href="#_9-·-non-goals" aria-label="Permalink to &quot;9 · Non-goals&quot;">​</a></h2><p>Per PRD-030: no billion-star Gaia render, no real-time cosmology, no AR/VR (explore-only), no fake to-scale galaxy distances, no invented exoplanet textures.</p>`,21)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
